void AutoStory::on_config_value_changed(void* object){
    COLLECTION.set_game(GAME_VERSION == GameVersion::LEAFGREEN ? 1 : 0, (int)(Starter)STARTER);
    COLLECTION.set_shiny_only(COLLECTION_SHINY);
}



